import{_ as d,c as e,o as t,a8 as c}from"./chunks/framework.jsZJWZJf.js";const _=JSON.parse('{"title":"象与骑象人 - 读书笔记","description":"","frontmatter":{"title":"象与骑象人 - 读书笔记","outline":[2,2]},"headers":[],"relativePath":"blog/read/books/象与骑象人.md","filePath":"blog/read/books/象与骑象人.md","lastUpdated":1795017144000}'),i={name:"blog/read/books/象与骑象人.md"};function s(r,a,v,n,o,l){return t(),e("div",null,[...a[0]||(a[0]=[c('<div class="social-psychology-notes" data-v-ca91644e><header class="reading-header" data-v-ca91644e><h1 data-v-ca91644e>象与骑象人</h1><p class="reading-byline" data-v-ca91644e>作者：乔纳森·海特</p><div class="reading-stats" data-v-ca91644e><span data-v-ca91644e>1 条摘抄</span><span data-v-ca91644e>微信读书</span></div></header><section class="reading-book" aria-label="书籍信息" data-v-ca91644e><div class="reading-cover" data-v-ca91644e><img src="https://cdn.weread.qq.com/weread/cover/58/YueWen_27416208/t6_YueWen_27416208.jpg" alt="象与骑象人封面" width="160" loading="lazy" data-v-ca91644e></div><div class="reading-book-info" data-v-ca91644e><p class="reading-book-title" data-v-ca91644e>书籍信息</p><dl class="reading-metadata" data-v-ca91644e><div data-v-ca91644e><dt data-v-ca91644e>书名</dt><dd data-v-ca91644e>象与骑象人</dd></div><div data-v-ca91644e><dt data-v-ca91644e>作者</dt><dd data-v-ca91644e>乔纳森·海特</dd></div><div data-v-ca91644e><dt data-v-ca91644e>出版社</dt><dd data-v-ca91644e>浙江人民出版社</dd></div><div data-v-ca91644e><dt data-v-ca91644e>出版时间</dt><dd data-v-ca91644e>2012-11-25 00:00:00</dd></div><div data-v-ca91644e><dt data-v-ca91644e>ISBN</dt><dd data-v-ca91644e>9787213050145</dd></div><div data-v-ca91644e><dt data-v-ca91644e>分类</dt><dd data-v-ca91644e>心理-心理学研究</dd></div></dl><a class="reading-original-link" href="https://weread.qq.com/web/reader/34132b0071a256903410e86" target="_blank" rel="noopener noreferrer" data-v-ca91644e>在微信读书中打开 <span aria-hidden="true" data-v-ca91644e>↗</span></a><details class="reading-description" data-v-ca91644e><summary data-v-ca91644e>书籍简介</summary><p data-v-ca91644e>《象与骑象人》作者乔纳森·海特是著名心理学家，坦普尔顿积极心理学奖获得者,伟大的思想家、积极心理学先锋派领袖。乔纳森·海特在《象与骑象人》中把人类思考了两千多年的问题，归结为10个假设，放在科学的天平上，到底哪些是真理，哪些是谬误？海特提出，人的心理可分为两半，一半像一头桀骜不驯的大象，另一半则是理性的骑象人。这两个分裂的部分，使得人们常常陷于理性与非理性的思想争战之中，而这种争战不仅会影响我们的决策，也会削弱我们的幸福感。乔纳森·海特融合了心理学、哲学、伦理学、宗教以及人类学等学科知识，大量引用了古今东西方哲学、文学与宗教中有关人的心理的看法，继而以现今神经科学与社会心理学的研究成果，来验证关于古老的关于幸福的假设。乔纳森·海特不仅让我们了解到，之前很多的所谓的“古老智慧”并不是真谛，而且还让我们懂得，如何积极地、理性地去寻找幸福和生命的意义。</p></details></div></section><h2 id="前言-10个幸福假设" tabindex="-1" data-v-ca91644e>前言 10个幸福假设 <a class="header-anchor" href="#前言-10个幸福假设" aria-label="Permalink to “前言 10个幸福假设”" data-v-ca91644e>​</a></h2><blockquote class="reading-excerpt" id="excerpt-001" data-v-ca91644e><span class="reading-excerpt-number" aria-hidden="true" data-v-ca91644e>001</span><div data-v-ca91644e><p data-v-ca91644e>莎士比亚以下这句话刚好简要地说明了这种现象：“事情没有好坏，是人的思想在作祟。”</p></div></blockquote></div>',1)])])}const g=d(i,[["render",s],["__scopeId","data-v-ca91644e"]]);export{_ as __pageData,g as default};
